#include <iostream>
#include <string>
#include "Student.cpp"
#include <vector>

using namespace std;

Student searchByFullName(vector<Student> &studentList, string fullName);

int main()
{

    vector<Student> studentList{};

    Student bob{};

    int User_idInput;
    cout << "Please enter student ID";
    cin >> User_idInput;
    bob.setID(User_idInput);

    string User_nameInput;
    cout << "please enter Student full name";
    cin >> User_nameInput;
    bob.setName(User_nameInput);

    int User_ageInput;
    cout << "please enter student age";
    cin >> User_ageInput;
    bob.setAge(User_ageInput);

    string User_majorInput;
    cout << "Please enter student's major";
    cin >> User_majorInput;
    bob.setMajor(User_majorInput);

    string User_emailInput;
    cout << "Please enter the student's email";
    cin >> User_emailInput;
    bob.setEmail(User_emailInput);
    cin.ignore();

    studentList.push_back(bob);

    Student example = searchByFullName(studentList, "bob");

    cout << "stuednt name is " << example.getName();
    cout << "stuednt name is " << example.getID() << endl;
    cout << "stuednt email is " << example.getEmail();
    cout << "stuednt major is " << example.getMajor() << endl;
    cout << "stuednt age is " << example.getAge();

    return 0;
}

